package mod.cdv.tnpc.tactical;
import java.util.*;import java.util.function.Supplier;
import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.neoforge.event.BuildCreativeModeTabContentsEvent;
public final class EggRegistration {
 static final String[] IDS={"bandit_passive_spawn_egg","bandit_neutral_spawn_egg","bandit_spawn_egg","military_hostile_spawn_egg"};
 static final int[] BASE={0x78A76A,0xB7A375,0x783C35,0x3C4930},SPOT={0xD8EBC4,0xE9D8AA,0xDCA64B,0x1B2117};static final List<Object> EGGS=new ArrayList<>();
 public static void install(Object bus){try{Object registry=Reflect.call(Reflect.type("net.neoforged.neoforge.registries.DeferredRegister"),"create",Reflect.field(Reflect.type("net.minecraft.core.registries.BuiltInRegistries"),"ITEM"),"tacznpcs");for(int i=0;i<IDS.length;i++){final int role=i;EGGS.add(Reflect.call(registry,"register",IDS[i],(Supplier<Object>)()->createEgg(role)));}Reflect.call(registry,"register",bus);Reflect.call(bus,"register",EggRegistration.class);CalmWorldEvents.install();}catch(Exception e){throw new IllegalStateException("Cannot register four NPC roles",e);}}
 public static Object createEgg(){return createEgg(2);}
 public static Object createEgg(int role){try{Object properties=Reflect.construct("net.minecraft.world.item.Item$Properties"),tag=Reflect.construct("net.minecraft.nbt.CompoundTag");Reflect.call(tag,"putString","id","tacznpcs:npc");Reflect.call(tag,"putString","template","__tactical_role_"+role);Reflect.call(tag,"putInt","npc22_role",role);Reflect.call(properties,"component",Reflect.field(Reflect.type("net.minecraft.core.component.DataComponents"),"ENTITY_DATA"),Reflect.call(Reflect.type("net.minecraft.world.item.component.CustomData"),"of",tag));Supplier<Object> type=()->{try{return Reflect.field(Reflect.type("mod.cdv.tnpc.entity.AutoGunOperator"),"NPC_TYPE");}catch(Exception e){throw new IllegalStateException(e);}};return Reflect.type("net.neoforged.neoforge.common.DeferredSpawnEggItem").getConstructor(Supplier.class,int.class,int.class,properties.getClass()).newInstance(type,BASE[role],SPOT[role],properties);}catch(Exception e){throw new IllegalStateException("Cannot create NPC role egg "+role,e);}}
 @SubscribeEvent public static void creative(BuildCreativeModeTabContentsEvent event){try{if(!Reflect.call(event,"getTabKey").equals(Reflect.field(Reflect.type("net.minecraft.world.item.CreativeModeTabs"),"SPAWN_EGGS")))return;Object visibility=Reflect.field(Reflect.type("net.minecraft.world.item.CreativeModeTab$TabVisibility"),"PARENT_AND_SEARCH_TABS");for(Object holder:EGGS)Reflect.call(event,"accept",Reflect.call(Reflect.call(holder,"get"),"getDefaultInstance"),visibility);}catch(Exception e){throw new IllegalStateException("Cannot add NPC eggs to creative tab",e);}}
 public static String resolveTemplate(String value){if(!value.equals("__tactical_bandit")&&!value.startsWith("__tactical_role_"))return value;try{Map<?,?> templates=(Map<?,?>)Reflect.field(Reflect.type("mod.cdv.tnpc.data.TemplateDataManager"),"TEMPLATES");for(String candidate:List.of("bandits","bandit","illagers","default"))if(templates.containsKey(candidate))return candidate;throw new IllegalStateException("No NPC templates loaded");}catch(Exception e){throw new IllegalStateException("Cannot resolve NPC template",e);}}
}
